Message[] batch = response.Messages.ToArray();
for (int i = 0; i < batch.Length; i++)
{
    Process(batch[i]);
}
// Length equals the batch size. No Add method — the batch is closed.

// Jagged: array of arrays (common in real code)
int[][] grid = [[1, 2], [3, 4, 5]];

// Rectangular: one block, fixed columns (rare)
int[,] matrix = new int[2, 3];
matrix[0, 1] = 7;

string[] names = ["alice", "bob"];
object[] boxed = names;          // compiles — arrays are covariant
boxed[0] = 42;                   // compiles as object
// throws ArrayTypeMismatchException at run time

byte[] buffer = ArrayPool<byte>.Shared.Rent(4096);
try
{
    int read = await stream.ReadAsync(buffer.AsMemory(0, 4096));
    Process(buffer.AsSpan(0, read));
}
finally
{
    ArrayPool<byte>.Shared.Return(buffer, clearArray: true);
}
